DO $$ BEGIN CREATE TYPE side_effect_level AS ENUM ('none','low','high'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE approval_status AS ENUM ('not_required','pending','approved','rejected','cancelled'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS tool_definitions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants ON DELETE CASCADE,name text NOT NULL,description text NOT NULL,input_schema_json jsonb NOT NULL,output_schema_json jsonb NOT NULL DEFAULT '{}',permissions jsonb NOT NULL DEFAULT '[]',side_effect_level side_effect_level NOT NULL DEFAULT 'none',timeout_ms int NOT NULL DEFAULT 10000,enabled boolean NOT NULL DEFAULT true,handler_type text NOT NULL,handler_config_json jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,name));
CREATE TABLE IF NOT EXISTS agent_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants ON DELETE CASCADE,assistant_id uuid REFERENCES assistants ON DELETE SET NULL,conversation_id uuid REFERENCES conversations ON DELETE SET NULL,user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,status text NOT NULL,input_json jsonb NOT NULL,output_json jsonb,state_json jsonb NOT NULL DEFAULT '{}',step_count int NOT NULL DEFAULT 0,trace_id text NOT NULL,started_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,error_json jsonb);
CREATE INDEX IF NOT EXISTS agent_runs_tenant_created_idx ON agent_runs(tenant_id,started_at DESC);
CREATE TABLE IF NOT EXISTS tool_calls(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants ON DELETE CASCADE,agent_run_id uuid NOT NULL REFERENCES agent_runs ON DELETE CASCADE,tool_definition_id uuid NOT NULL REFERENCES tool_definitions ON DELETE RESTRICT,input_json jsonb NOT NULL,validated_input_json jsonb NOT NULL,output_json jsonb,status text NOT NULL,approval_status approval_status NOT NULL DEFAULT 'not_required',approval_reason text,approved_by uuid REFERENCES users ON DELETE SET NULL,approved_at timestamptz,idempotency_key text,latency_ms int,error_json jsonb,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,idempotency_key));
CREATE INDEX IF NOT EXISTS tool_calls_tenant_status_idx ON tool_calls(tenant_id,approval_status,created_at DESC);
CREATE TABLE IF NOT EXISTS support_tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants ON DELETE CASCADE,title text NOT NULL,description text NOT NULL,status text NOT NULL DEFAULT 'open',idempotency_key text NOT NULL,created_by uuid NOT NULL REFERENCES users,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS workflow_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users,assistant_id uuid REFERENCES assistants ON DELETE SET NULL,conversation_id uuid REFERENCES conversations ON DELETE SET NULL,status text NOT NULL,input_json jsonb NOT NULL,state_json jsonb NOT NULL,trace_id text NOT NULL,started_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,error_json jsonb);
CREATE TABLE IF NOT EXISTS workflow_node_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants ON DELETE CASCADE,workflow_run_id uuid NOT NULL REFERENCES workflow_runs ON DELETE CASCADE,node_name text NOT NULL,status text NOT NULL,input_summary_json jsonb NOT NULL DEFAULT '{}',output_summary_json jsonb NOT NULL DEFAULT '{}',latency_ms int NOT NULL,error_json jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS workflow_nodes_tenant_run_idx ON workflow_node_runs(tenant_id,workflow_run_id,created_at);
CREATE TABLE IF NOT EXISTS plans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE,name text NOT NULL,limits_json jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tenant_subscriptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL UNIQUE REFERENCES tenants ON DELETE CASCADE,plan_id uuid NOT NULL REFERENCES plans,starts_at timestamptz NOT NULL DEFAULT now(),ends_at timestamptz,status text NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS quota_buckets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants ON DELETE CASCADE,bucket_type text NOT NULL,period_start date NOT NULL,used numeric(20,4) NOT NULL DEFAULT 0,bonus numeric(20,4) NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,bucket_type,period_start));
CREATE TABLE IF NOT EXISTS api_keys(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants ON DELETE CASCADE,name text NOT NULL,key_hash text NOT NULL UNIQUE,prefix text NOT NULL,scopes jsonb NOT NULL,expires_at timestamptz,last_used_at timestamptz,revoked_at timestamptz,created_by uuid NOT NULL REFERENCES users,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS api_keys_tenant_idx ON api_keys(tenant_id,created_at DESC);
CREATE TABLE IF NOT EXISTS evaluation_datasets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants ON DELETE CASCADE,name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,name));
CREATE TABLE IF NOT EXISTS evaluation_cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants ON DELETE CASCADE,dataset_id uuid NOT NULL REFERENCES evaluation_datasets ON DELETE CASCADE,question text NOT NULL,expected_answer text NOT NULL,expected_document_ids jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS evaluation_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants ON DELETE CASCADE,dataset_id uuid NOT NULL REFERENCES evaluation_datasets ON DELETE CASCADE,status text NOT NULL,metrics_json jsonb NOT NULL DEFAULT '{}',trace_id text NOT NULL,started_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
INSERT INTO plans(code,name,limits_json) VALUES('development','Development','{"monthlyTokens":10000000,"dailyRequests":10000,"concurrentRuns":10,"storageBytes":10737418240,"knowledgeBaseCount":100,"assistantCount":100}') ON CONFLICT(code) DO NOTHING;
INSERT INTO tenant_subscriptions(tenant_id,plan_id) SELECT t.id,p.id FROM tenants t CROSS JOIN plans p WHERE p.code='development' ON CONFLICT(tenant_id) DO NOTHING;
